:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #263344;
  background: #e9f1eb;
}
* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 36px 18px;
  display: grid;
  place-items: center;
  background-color: #e9f1eb;
  background-image: radial-gradient(#cbdccf 1.2px, transparent 1.2px);
  background-size: 22px 22px;
}
.shop {
  width: min(100%, 590px);
  padding: 34px;
  border: 2px solid #263344;
  border-radius: 20px;
  background: #fffdf7;
  box-shadow: 8px 8px 0 #263344;
}
.shop-header { text-align: center; }
.shop-mark {
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  margin: 0 auto 16px;
  border: 2px solid #263344;
  border-radius: 14px;
  color: #fffdf7;
  background: #e87952;
  font-size: 28px;
}
.eyebrow {
  margin: 0 0 6px;
  color: #657467;
  font-size: 0.78rem;
  font-weight: 750;
  letter-spacing: 0.12em;
}
h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.6rem); line-height: 1.1; }
.subtitle { margin: 10px 0 24px; color: #657467; }
.sales {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border: 2px solid #263344;
  border-radius: 13px;
  color: #fffdf7;
  background: #4c7868;
}
.sales span { font-weight: 650; }
.sales strong { font-size: 1.65rem; font-variant-numeric: tabular-nums; }
.inventory { margin-top: 25px; }
.section-heading { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 10px; }
h2 { margin: 0; font-size: 1.15rem; }
.section-heading span { color: #657467; font-size: 0.9rem; }
.item-list { display: grid; gap: 10px; margin: 0; padding: 0; list-style: none; }
.item {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border: 1.5px solid #d9dfd6;
  border-radius: 12px;
  background: #fff;
}
.item-icon { text-align: center; font-size: 1.7rem; }
.item-name { display: block; font-weight: 700; }
.item-price { display: block; margin-top: 2px; color: #657467; font-size: 0.9rem; }
.stock { margin-top: 4px; color: #4c7868; font-size: 0.9rem; font-weight: 650; }
.stock.sold-out { color: #b84e38; }
.actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 7px; }
button {
  min-height: 42px;
  padding: 8px 11px;
  border: 2px solid #263344;
  border-radius: 9px;
  color: #263344;
  background: #fffdf7;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
  transition: transform 120ms ease, background-color 120ms ease, box-shadow 120ms ease;
}
button.sell { color: #fffdf7; background: #e87952; }
button:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 3px 0 #263344; }
button:active:not(:disabled) { transform: translateY(1px); box-shadow: none; }
button:focus-visible { outline: 3px solid #4c7868; outline-offset: 3px; }
button:disabled { color: #657467; background: #e9ece6; cursor: not-allowed; opacity: 0.7; }
footer { margin-top: 22px; color: #657467; text-align: center; font-size: 0.9rem; }
@media (max-width: 480px) {
  body { padding: 18px 12px; }
  .shop { padding: 24px 16px; box-shadow: 5px 5px 0 #263344; }
  .item { grid-template-columns: 36px minmax(0, 1fr); gap: 9px; }
  .actions { grid-column: 1 / -1; justify-content: stretch; }
  .actions button { flex: 1; }
}

const items = [
  { name: "Berry Soda", icon: "🥤", price: 2.50, stock: 8 },
  { name: "Pixel Cookie", icon: "🍪", price: 1.75, stock: 6 },
  { name: "Lucky Plant", icon: "🪴", price: 5.00, stock: 4 },
  { name: "Star Sticker", icon: "⭐", price: 0.75, stock: 10 },
  { name: "Pocket Game", icon: "🎮", price: 12.00, stock: 3 }
];

let salesTotal = 0;
const itemList = document.querySelector("#item-list");
const salesDisplay = document.querySelector("#sales-total");
const money = amount => `$${amount.toFixed(2)}`;

function renderItems() {
  itemList.replaceChildren();
  items.forEach((item, index) => {
    const row = document.createElement("li");
    row.className = "item";
    const icon = document.createElement("span");
    icon.className = "item-icon";
    icon.setAttribute("aria-hidden", "true");
    icon.textContent = item.icon;
    const info = document.createElement("div");
    const name = document.createElement("span");
    name.className = "item-name";
    name.textContent = item.name;
    const price = document.createElement("span");
    price.className = "item-price";
    price.textContent = `${money(item.price)} each`;
    const stock = document.createElement("div");
    stock.className = `stock${item.stock === 0 ? " sold-out" : ""}`;
    stock.textContent = item.stock === 0 ? "Sold out" : `${item.stock} in stock`;
    info.append(name, price, stock);
    const actions = document.createElement("div");
    actions.className = "actions";
    const sell = document.createElement("button");
    sell.className = "sell";
    sell.type = "button";
    sell.textContent = "Sell 1";
    sell.setAttribute("aria-label", `Sell one ${item.name}`);
    sell.disabled = item.stock === 0;
    sell.addEventListener("click", () => {
      if (item.stock > 0) {
        item.stock -= 1;
        salesTotal += item.price;
        salesDisplay.textContent = money(salesTotal);
        renderItems();
      }
    });
    const restock = document.createElement("button");
    restock.type = "button";
    restock.textContent = "Restock +10";
    restock.setAttribute("aria-label", `Restock ${item.name} by 10`);
    restock.addEventListener("click", () => {
      item.stock += 10;
      renderItems();
    });
    actions.append(sell, restock);
    row.append(icon, info, actions);
    itemList.append(row);
  });
}

renderItems();
